// Hand-written. Not generated by Speakeasy.
//
// Authlete returns these lists in an order of its own, which is not the order
// they were sent in. The KeepOrder plan modifiers hold the state value when
// config and state differ only by order, which stops the list itself showing a
// diff. It is not enough on its own: Read overwrites state with whatever the
// API returned, so after a refresh the stored order differs from the
// configured one, the resource is marked as changing, and every computed
// attribute on it plans as unknown. The list is no longer the attribute that
// shows the change, but the plan still never settles.
//
// So the order is held on the way in as well. Read captures the prior state,
// refreshes, and puts back any list whose elements are unchanged.
//
// The call sites are in generated files, so scripts/patch-list-order.py
// reapplies them after regeneration and --check guards them in CI.
package provider

import (
	"sort"

	tfTypes "github.com/authlete/terraform-provider-authlete/v3/internal/provider/types"
	"github.com/hashicorp/terraform-plugin-framework/types"
)

// keepOrder returns prev when it holds the same elements as next, so a
// response that differs only by order leaves state alone. Any real edit,
// including one that also reorders, returns next.
func keepOrder(prev, next []types.String) []types.String {
	if prev == nil || !sameStringElements(prev, next) {
		return next
	}
	return prev
}

// sameStringElements compares two lists as multisets. A null or unknown
// element makes them incomparable: holding the old order would then risk
// hiding a real change, so they are reported as different.
func sameStringElements(a, b []types.String) bool {
	if len(a) != len(b) {
		return false
	}

	keys := func(vals []types.String) ([]string, bool) {
		out := make([]string, 0, len(vals))
		for _, v := range vals {
			if v.IsNull() || v.IsUnknown() {
				return nil, false
			}
			out = append(out, v.ValueString())
		}
		sort.Strings(out)
		return out, true
	}

	ka, ok := keys(a)
	if !ok {
		return false
	}
	kb, ok := keys(b)
	if !ok {
		return false
	}
	for i := range ka {
		if ka[i] != kb[i] {
			return false
		}
	}
	return true
}

// keepServiceListOrder restores the stored order of every service list that
// Authlete reorders. Nine of them; supported_scopes is excluded because it is
// a list of objects whose server-filled fields differ by more than order, so
// reordering cannot be told apart from an edit.
func keepServiceListOrder(prev, cur *ServiceResourceModel) {
	if prev == nil || cur == nil {
		return
	}
	cur.SupportedAttachments = keepOrder(prev.SupportedAttachments, cur.SupportedAttachments)
	cur.SupportedClaimTypes = keepOrder(prev.SupportedClaimTypes, cur.SupportedClaimTypes)
	cur.SupportedClaims = keepOrder(prev.SupportedClaims, cur.SupportedClaims)
	cur.SupportedDisplays = keepOrder(prev.SupportedDisplays, cur.SupportedDisplays)
	cur.SupportedGrantTypes = keepOrder(prev.SupportedGrantTypes, cur.SupportedGrantTypes)
	cur.SupportedPromptValues = keepOrder(prev.SupportedPromptValues, cur.SupportedPromptValues)
	cur.SupportedResponseTypes = keepOrder(prev.SupportedResponseTypes, cur.SupportedResponseTypes)
	cur.SupportedServiceProfiles = keepOrder(prev.SupportedServiceProfiles, cur.SupportedServiceProfiles)
	cur.SupportedTokenAuthMethods = keepOrder(prev.SupportedTokenAuthMethods, cur.SupportedTokenAuthMethods)
	cur.SupportedScopes = keepScopeOrder(prev.SupportedScopes, cur.SupportedScopes)
}

// keepScopeOrder puts the stored scopes back in the order state already held,
// matching on name.
//
// supported_scopes is a list of objects rather than strings, so keepOrder does
// not apply: the elements cannot be compared whole, because Authlete fills in
// default_entry on a scope the configuration named and nothing else. Matching
// on name instead reorders without touching content, so an edit to a
// description still reaches state and still shows as a change.
//
// Authlete sorts this list alphabetically. Measured: zeta, alpha, mike, beta
// comes back as alpha, beta, mike, zeta.
func keepScopeOrder(prev, next []tfTypes.Scope) []tfTypes.Scope {
	if len(prev) == 0 || len(prev) != len(next) {
		return next
	}

	byName := make(map[string]tfTypes.Scope, len(next))
	for _, s := range next {
		if s.Name.IsNull() || s.Name.IsUnknown() {
			return next
		}
		if _, dup := byName[s.Name.ValueString()]; dup {
			return next
		}
		byName[s.Name.ValueString()] = s
	}

	out := make([]tfTypes.Scope, 0, len(prev))
	for _, s := range prev {
		if s.Name.IsNull() || s.Name.IsUnknown() {
			return next
		}
		got, present := byName[s.Name.ValueString()]
		if !present {
			// A scope was added or removed, so there is no order to keep.
			return next
		}
		out = append(out, got)
	}
	return out
}

// keepClientListOrder does the same for the client lists.
//
// requestable_scopes lives inside the extension object rather than at the top
// level, which is why it was missed when the others were done. Authlete
// returns it in an order of its own, so ["read","write"] came back as
// ["write","read"] and the plan showed a diff although nothing had changed.
func keepClientListOrder(prev, cur *ClientResourceModel) {
	if prev == nil || cur == nil {
		return
	}
	cur.GrantTypes = keepOrder(prev.GrantTypes, cur.GrantTypes)
	cur.ResponseModes = keepOrder(prev.ResponseModes, cur.ResponseModes)
	cur.ResponseTypes = keepOrder(prev.ResponseTypes, cur.ResponseTypes)

	if prev.Extension != nil && cur.Extension != nil {
		cur.Extension.RequestableScopes = keepOrder(
			prev.Extension.RequestableScopes, cur.Extension.RequestableScopes)
	}
}
